using UnityEngine;
using UnityEngine.Rendering;
namespace BWVR {
public sealed partial class WorldBrush {
 public const float WindCost=1.5f,WindInterval=.25f,WindSpeedLimit=8;
 BeachBall[] windBalls;ConstructionBlock[] windBlocks;ParticleSystem leaves;
 void BuildWind(){windBalls=nav.GetComponentsInChildren<BeachBall>();windBlocks=nav.GetComponentsInChildren<ConstructionBlock>();var go=new GameObject("Player wind fan — 32 leaf motes");go.transform.SetParent(transform,false);leaves=go.AddComponent<ParticleSystem>();leaves.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=leaves.main;main.playOnAwake=false;main.loop=true;main.startLifetime=.5f;main.startSpeed=nav.Scale*14;main.startSize=new ParticleSystem.MinMaxCurve(nav.Scale*.2f,nav.Scale*.5f);main.startColor=new Color(.65f,.85f,.5f,.7f);main.maxParticles=32;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=leaves.emission;emission.rateOverTime=40;var shape=leaves.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=18;shape.radius=nav.Scale*2;var fade=leaves.colorOverLifetime;fade.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.6f,.15f),new GradientAlphaKey(0,1)});fade.color=gradient;var renderer=leaves.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;}
 bool WindDirection(Vector3 direction,out Vector3 flat){flat=new Vector3(direction.x,0,direction.z);if(!HybridState.Number(direction.x,-10000,10000)||!HybridState.Number(direction.y,-10000,10000)||!HybridState.Number(direction.z,-10000,10000)||flat.sqrMagnitude<.0001f)return false;flat.Normalize();return true;}
 bool InFan(Vector3 at,Vector3 point,Vector3 direction){var delta=(at-point)/nav.Scale;if(Mathf.Abs(delta.y)>12)return false;delta.y=0;float along=Vector3.Dot(delta,direction);float side=Vector3.Dot(delta,Vector3.Cross(Vector3.up,direction));return along>=-2&&along<=24&&Mathf.Abs(side)<=4+Mathf.Max(0,along)*.25f;}
 bool Reserved(CarryItem item){if(item==null||item.held||!item.gameObject.activeInHierarchy||item.GetComponent<DiscoveryObject>()?.Owner!=null||item.GetComponent<CreatureAffordance>()?.host!=null)return true;var target=item.GetComponent<HybridTarget>();return target!=null&&Season.Hybrid.intention.active&&Season.Hybrid.intention.target==target.id;}
 static Vector3 Nudge(Vector3 velocity,Vector3 direction){var horizontal=new Vector3(velocity.x,0,velocity.z);var desired=Vector3.ClampMagnitude(horizontal+direction*.85f,WindSpeedLimit);return Vector3.ClampMagnitude(desired-horizontal,.85f);}
 int PushWind(Vector3 point,Vector3 direction,bool apply){int count=0;
  foreach(var ball in windBalls){if(count>=8)break;if(ball==null||ball.Body==null||ball.Body.isKinematic||Reserved(ball.GetComponent<CarryItem>())||ball.FetchReserved||ball.Player!=null||ball.PeerGame||!InFan(nav.ToWorld(ball.Body.position),point,direction))continue;var velocity=ball.Body.linearVelocity;var delta=Nudge(velocity,direction);if(delta.sqrMagnitude<.000001f)continue;if(apply)ball.EnvironmentalImpulse(delta);count++;}
  foreach(var block in windBlocks){if(count>=8)break;if(block==null||block.Body==null||block.Body.isKinematic||block.Attached||block.VillagerOwner!=null||block.Site.Repairer!=null||Reserved(block.Item)||!InFan(block.Site.World(block.Body.position),point,direction))continue;var local=Quaternion.Inverse(block.Site.transform.rotation)*direction;local.y=0;local.Normalize();var delta=Nudge(block.Body.linearVelocity,local);if(delta.sqrMagnitude<.000001f)continue;if(apply){block.Body.linearVelocity+=delta;block.Body.angularVelocity=Vector3.ClampMagnitude(block.Body.angularVelocity,3);block.Body.WakeUp();}count++;}
  return count;
 }
 public bool CanWind(Vector3 point,Vector3 direction,out string reason){EnsureSeason();reason="";if(Season.paused||miracles.Suspended){reason="Paused";return false;}if(!GroundPoint(point)||!WindDirection(direction,out var flat)){reason="Aim the fan across island ground";return false;}if(!miracles.CanAfford(WindCost)){reason="Not enough spiritual energy";return false;}if(PushWind(point,flat,false)==0){reason="Aim at loose, unreserved blocks or a free ball";return false;}return true;}
 public bool WindPulse(Vector3 point,Vector3 direction){EnsureSeason();if(Season.Hybrid.time<nextPulse){Reason="Fan is settling";return false;}if(!CanWind(point,direction,out var reason)){Reason=reason;return false;}WindDirection(direction,out var flat);int affected=PushWind(point,flat,true);if(affected==0)return false;miracles.SpendEnergy(WindCost);nextPulse=Season.Hybrid.time+WindInterval;Pulses++;Point=point;Reason="";creature.InvalidateLesson("Player wind fan is not creature work");Season.Hybrid.Evidence.Add(Season.Hybrid.time,EvidenceKind.Miracle,EvidenceSource.PlayerMiracle,CreatureAction.IdleOrObserve,"ground-wind-fan","Capped wind nudge; affected "+affected+"; cost "+miracles.EnergyCost(WindCost));IslandAudio.Cue(IslandSound.Gust,point,GetEntityId().GetHashCode(),.45f);return true;}
 public bool ProcessWind(Vector3 point,Vector3 direction,bool held,float dt,bool aimValid=true){EnsureSeason();StopRain();StopWhirlwind();if(!held||Season.paused||miracles.Suspended||!HybridState.Number(dt,0,1)){Stop();return false;}heldFor+=Mathf.Min(dt,.05f);if(!miracles.CanAfford(WindCost)){restRequired=true;StopWind();Reason="Release the trigger: energy exhausted";return false;}if(restRequired||heldFor>6||strokePulses>=24){StopWind();Reason="Release the trigger to rest the fan";return false;}if(!aimValid){StopWind();Reason="Aim at a supported patch of island ground";return false;}if(!CanWind(point,direction,out var reason)){StopWind();Reason=reason;return false;}bool applied=false;if(Season.Hybrid.time>=nextPulse){applied=WindPulse(point,direction);if(applied)strokePulses++;}Active=true;Point=point;WindDirection(direction,out var flat);leaves.transform.SetPositionAndRotation(point+Vector3.up*nav.Scale*3,Quaternion.LookRotation(flat));if(!leaves.isPlaying)leaves.Play();return applied;}
 void StopWind(){Active=false;if(leaves!=null)leaves.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
}
}
